CREATE TABLE IF NOT EXISTS outbox_events (id UUID PRIMARY KEY, restaurant_id UUID NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE, event_type TEXT NOT NULL, aggregate_type TEXT NOT NULL, aggregate_id UUID NOT NULL, payload JSONB NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','PROCESSING','PROCESSED','FAILED')), attempts INTEGER NOT NULL DEFAULT 0, available_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), failure_reason TEXT, processed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(restaurant_id,event_type,aggregate_type,aggregate_id));
CREATE INDEX IF NOT EXISTS outbox_pending_idx ON outbox_events(status,available_at);
CREATE TABLE IF NOT EXISTS notifications (id UUID PRIMARY KEY, restaurant_id UUID NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE, outbox_event_id UUID NOT NULL REFERENCES outbox_events(id) ON DELETE RESTRICT, event_type TEXT NOT NULL, recipient_phone TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'QUEUED' CHECK(status IN ('QUEUED','SENDING','SENT','FAILED','SUPPRESSED')), idempotency_key TEXT NOT NULL UNIQUE, body TEXT NOT NULL, provider_message_id TEXT, provider_status TEXT, error_message TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), sent_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS messages (id UUID PRIMARY KEY, restaurant_id UUID NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE, notification_id UUID NOT NULL REFERENCES notifications(id) ON DELETE CASCADE, provider_message_id TEXT, status TEXT NOT NULL DEFAULT 'QUEUED', error_code TEXT, error_message TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(provider_message_id));
